const LINE = 2.6;
const f2 = (n)=>Math.round(100 * n) / 100;
const disc = (cx, cy, r)=>`M${f2(cx - r)} ${f2(cy)}a${f2(r)} ${f2(r)} 0 1 0 ${f2(2 * r)} 0a${f2(r)} ${f2(r)} 0 1 0 ${f2(-2 * r)} 0Z`;
function spiral() {
    let d = '';
    for(let i = 0; i <= 40; i++){
        const t = i / 40 * 3.4 * Math.PI;
        const r = 0.6 + 1.5 * t;
        d += `${i ? 'L' : 'M'}${f2(12 + r * Math.cos(t))} ${f2(12 + r * Math.sin(t))}`;
    }
    return d;
}
